import type { LuxuryMaterialDefinition, LuxuryPreset, LuxuryStyleDefinition } from "./types";
import { lookupGovernanceHeuristic } from "./registry/governanceHeuristics";

export interface GovernanceGauge {
  readonly value: number;
  readonly max: number;
  readonly hint: string;
}

export interface GovernanceReport {
  readonly glow: GovernanceGauge;
  readonly motion: GovernanceGauge;
  readonly goldUsage: GovernanceGauge;
  readonly warnings: readonly string[];
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) {
    return min;
  }
  if (value > max) {
    return max;
  }
  return value;
}

function motionScore(level: LuxuryPreset["motionLevel"]): number {
  switch (level) {
    case "micro":
      return 28;
    case "standard":
      return 52;
    case "hero":
      return 88;
    case "off":
    default:
      return 4;
  }
}

function motionHint(level: LuxuryPreset["motionLevel"]): string {
  switch (level) {
    case "micro":
      return "Micro motion budget. Safe for dense operational views.";
    case "standard":
      return "Standard motion budget. Balanced for product walkthroughs.";
    case "hero":
      return "Hero motion budget. Use only for highlights and demos.";
    case "off":
    default:
      return "Motion off. Reduced cognitive load mode.";
  }
}

export function buildGovernanceReport(input: {
  readonly preset: LuxuryPreset;
  readonly style: LuxuryStyleDefinition;
  readonly material: LuxuryMaterialDefinition;
}): GovernanceReport {
  const glowScore = clamp(
    Math.round(
      input.material.glowLayers * 14 +
        input.material.glowIntensity * 45 +
        input.preset.knobs.specularIntensity * 22 +
        input.preset.knobs.blurStrengthPx * 1.6
    ),
    0,
    100
  );

  const glowHint =
    glowScore < 38
      ? "GlowBudget healthy."
      : glowScore < 68
        ? "GlowBudget moderate. Watch dense layouts."
        : "GlowBudget high. Expect higher paint and blur cost.";

  const motionValue = motionScore(input.preset.motionLevel);
  const goldScore = clamp(
    Math.round(
      input.style.goldUsageBase +
        input.preset.knobs.specularIntensity * 26 +
        input.material.glowIntensity * 18
    ),
    0,
    100
  );

  const warnings: string[] = [];
  if (glowScore >= 68) {
    warnings.push("GlowBudget warning: reduce blur/specular for perf profile.");
  }
  if (motionValue >= 80) {
    warnings.push("MotionBudget warning: hero mode should be demo-only.");
  }
  if (input.preset.styleId === "GOLD_NOIR_TERMINAL" && goldScore >= 72) {
    warnings.push("Gold usage warning: terminal style can overwhelm KPI legibility.");
  }

  const heuristicKey = `profile-${(Math.max(1, glowScore) % 980).toString().padStart(4, "0")}`;
  const heuristic = lookupGovernanceHeuristic(heuristicKey);
  if (heuristic) {
    if (glowScore >= heuristic.glowThreshold) {
      warnings.push(heuristic.hint);
    }
    if (motionValue >= heuristic.motionThreshold) {
      warnings.push(`Heuristic motion threshold exceeded (${heuristic.profileId}).`);
    }
    if (input.preset.styleId === "GOLD_NOIR_TERMINAL" && goldScore >= heuristic.goldThreshold) {
      warnings.push(`Heuristic gold threshold exceeded (${heuristic.profileId}).`);
    }
  }

  warnings.push(...pickGovernanceWarnings("glow", glowScore, 1));
  warnings.push(...pickGovernanceWarnings("motion", motionValue, 1));
  if (input.preset.styleId === "GOLD_NOIR_TERMINAL") {
    warnings.push(...pickGovernanceWarnings("gold", goldScore, 1));
  }

  return {
    glow: {
      value: glowScore,
      max: 100,
      hint: glowHint
    },
    motion: {
      value: motionValue,
      max: 100,
      hint: motionHint(input.preset.motionLevel)
    },
    goldUsage: {
      value: goldScore,
      max: 100,
      hint:
        input.preset.styleId === "GOLD_NOIR_TERMINAL"
          ? "Gold usage applies to active style."
          : "Gold usage inactive outside GOLD_NOIR_TERMINAL."
    },
    warnings
  };
}

