export function pickGovernanceWarnings(channel: "glow" | "motion" | "gold", value: number, limit = 3): readonly string[] {
  return GOVERNANCE_WARNING_LIBRARY.filter((item) => item.channel === channel && value >= item.threshold).slice(0, limit).map((item) => item.message);
}

